:root {
  --bg: #faf7f0;
  --bg-alt: #f4ede3;
  --white: #ffffff;
  --ink: #1b1b1b;
  --muted: #5c5750;
  --dim: #8c857b;
  --line: #e3dccf;
  --gold: #c0994f;
  --green: #2a4236;
  --dark: #1b1b1b;
  --f-display: var(--font-display), "Times New Roman", serif;
  --f-body: var(--font-body), system-ui, sans-serif;
  --f-mono: var(--font-mono), ui-monospace, monospace;
  --w: 1160px;
}
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--ink); font-family: var(--f-body); font-size: 16px; line-height: 1.65; -webkit-font-smoothing: antialiased; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; margin: 0; padding: 0; }
h1, h2, h3, p { margin: 0; }
:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
.container { width: 100%; max-width: calc(var(--w) + 48px); margin: 0 auto; padding: 0 24px; }
.dim { color: var(--dim); } .small { font-size: 12px; }

/* type */
h1, h2, h3, .logo-name, .footer-logo, .footer-phone, .quote { font-family: var(--f-display); font-weight: 400; letter-spacing: -0.02em; }
h1 { font-size: clamp(40px, 6vw, 68px); line-height: 1.02; max-width: 16ch; }
h2 { font-size: clamp(28px, 3.6vw, 42px); line-height: 1.1; }
h3 { font-size: 22px; line-height: 1.2; }
.eyebrow, .mono { font-family: var(--f-mono); font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; }
.eyebrow { color: var(--ink); margin-bottom: 18px; }
.lead { color: var(--muted); font-size: 17px; max-width: 58ch; margin-top: 22px; }
.prose p { color: var(--muted); margin-bottom: 18px; max-width: 62ch; }

/* buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; padding: 14px 22px; font-family: var(--f-mono); font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; border: 1px solid var(--dark); border-radius: 6px; cursor: pointer; transition: background .2s, color .2s; }
.btn--dark { background: var(--dark); color: #fff; }
.btn--dark:hover { background: #000; }
.btn--line { background: transparent; color: var(--ink); border-color: var(--line); }
.btn--line:hover { border-color: var(--ink); }
.btn--sm { padding: 12px 22px; }
.btn--block { width: 100%; }
.link-u { font-family: var(--f-mono); font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; display: inline-flex; gap: 8px; align-items: center; border-bottom: 1px solid var(--gold); padding-bottom: 3px; }

/* header */
.header { position: sticky; top: 0; z-index: 50; background: rgba(250,247,240,.94); backdrop-filter: blur(8px); border-bottom: 1px solid var(--line); }
.header-in { display: flex; align-items: center; justify-content: space-between; gap: 24px; height: 80px; }
.logo { display: flex; align-items: center; gap: 12px; }
.logo-name { font-size: 28px; line-height: 1; }
.logo-sub { font-family: var(--f-mono); font-size: 9px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted); line-height: 1.3; }
.nav { display: flex; gap: 30px; }
.nav a { font-family: var(--f-mono); font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted); transition: color .2s; }
.nav a:hover, .nav a[aria-current="page"] { color: var(--ink); }
.nav-phone-m { display: none; }
.header-cta { display: flex; align-items: center; gap: 16px; }
.header-phone { display: inline-flex; gap: 8px; align-items: center; font-family: var(--f-mono); font-size: 11px; letter-spacing: 0.16em; }
.burger { display: none; width: 40px; height: 40px; background: none; border: 0; position: relative; cursor: pointer; }
.burger span { position: absolute; left: 9px; right: 9px; height: 1.5px; background: var(--ink); transition: transform .2s; }
.burger span:first-child { top: 15px; } .burger span:last-child { top: 24px; }
.burger[aria-expanded="true"] span:first-child { transform: translateY(4.5px) rotate(45deg); }
.burger[aria-expanded="true"] span:last-child { transform: translateY(-4.5px) rotate(-45deg); }

/* breadcrumb + page hero */
.crumbs { font-family: var(--f-mono); font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--dim); margin-bottom: 30px; display: flex; flex-wrap: wrap; gap: 8px; }
.crumbs i { font-style: normal; margin: 0 8px 0 0; } .crumbs b { color: var(--ink); font-weight: 500; }
.crumbs a:hover { color: var(--ink); }
.hero-page { padding: 44px 0 64px; border-bottom: 1px solid var(--line); }

/* sections */
.section { padding: 80px 0; }
.section--white { background: var(--white); }
.section--alt { background: var(--bg-alt); }
.section + .section { border-top: 1px solid var(--line); }
.split { display: grid; grid-template-columns: 1.15fr 1fr; gap: 72px; align-items: start; }
.split--rev { grid-template-columns: 1fr 1.15fr; }

/* photo */
.photo { position: relative; overflow: hidden; background: #e9dfce; width: 100%; }
.photo img { width: 100%; height: 100%; object-fit: cover; }
.photo-ph { position: absolute; inset: 0; display: grid; place-items: center; background: linear-gradient(135deg, #e8dcc7, #d6c3a2); }
.photo-ph span { font-family: var(--f-mono); font-size: 10px; letter-spacing: .12em; color: #8a7655; }
.caption { font-family: var(--f-mono); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--dim); margin-top: 10px; }

/* cards grid */
.grid3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 56px 32px; }
.card .photo { margin-bottom: 22px; }
.card h3 { margin-bottom: 8px; }
.card p { color: var(--muted); font-size: 15px; margin-bottom: 16px; }
.card .photo img { transition: transform .6s; } .card:hover .photo img { transform: scale(1.03); }

/* urgent strip */
.urgent { display: flex; gap: 20px; align-items: center; justify-content: space-between; background: var(--bg-alt); border: 1px solid var(--line); padding: 28px 32px; margin-top: 56px; }
.urgent-l { display: flex; gap: 18px; align-items: flex-start; }
.urgent h3 { font-size: 26px; margin: 4px 0 6px; } .urgent p:last-child { color: var(--muted); font-size: 15px; }

/* before/after */
.ba { cursor: ew-resize; touch-action: pan-y; user-select: none; -webkit-user-select: none; position: relative; aspect-ratio: 4 / 3; overflow: hidden; background: #e9dfce; }
.ba-layer { position: absolute; inset: 0; } .ba-layer .photo { height: 100%; aspect-ratio: auto !important; }
.ba-tag { position: absolute; top: 12px; font-family: var(--f-mono); font-size: 10px; letter-spacing: .16em; text-transform: uppercase; padding: 5px 10px; z-index: 2; }
.ba-tag--l { left: 12px; background: var(--dark); color: #fff; } .ba-tag--r { right: 12px; background: #fff; color: var(--ink); }
.ba-handle { position: absolute; top: 50%; width: 38px; height: 38px; margin: -19px 0 0 -19px; border-radius: 50%; background: var(--dark); color: #fff; display: grid; place-items: center; z-index: 3; pointer-events: none; box-shadow: 0 0 0 2px #fff; }
.ba-line { position: absolute; top: 0; bottom: 0; width: 1px; margin-left: -.5px; background: #fff; z-index: 2; pointer-events: none; }
.ba img { pointer-events: none; -webkit-user-drag: none; }
.ba:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
.work-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 56px 32px; }
.work-meta { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; margin: 20px 0 8px; }
.work-meta .mono { font-size: 9px; color: var(--dim); }
.work p { color: var(--muted); font-size: 15px; max-width: 56ch; }
.note { border-top: 1px solid var(--line); margin-top: 56px; padding-top: 16px; font-size: 12px; font-style: italic; color: var(--dim); max-width: 640px; }

/* cta band */
.cta-band { background: #f3ebe0; border-top: 1px solid var(--line); padding: 72px 0; }
.cta-in { display: flex; justify-content: space-between; align-items: center; gap: 40px; }
.cta-in p { color: var(--muted); margin-top: 14px; max-width: 54ch; }
.cta-btns { display: flex; gap: 10px; flex-shrink: 0; }

/* footer */
.footer { background: var(--dark); color: #e9e4da; padding-top: 72px; }
.footer-grid { display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr; gap: 40px; padding-bottom: 64px; }
.footer-logo { font-size: 30px; margin-bottom: 16px; }
.footer-desc { color: #c9c3b8; font-size: 15px; max-width: 34ch; }
.footer-phone { display: inline-block; font-size: 26px; margin: 22px 0 18px; border-bottom: 1px solid var(--gold); }
.footer address { font-style: normal; font-size: 14px; line-height: 1.7; }
.footer-h { font-family: var(--f-mono); font-size: 10px; letter-spacing: .18em; text-transform: uppercase; color: #8c857b; margin-bottom: 20px; }
.footer li { margin-bottom: 11px; font-size: 14px; } .footer li a:hover { color: #fff; text-decoration: underline; text-underline-offset: 4px; }
.footer-rating { display: flex; align-items: center; gap: 8px; font-size: 14px; margin-bottom: 18px; }
.footer-hours { font-size: 14px; margin-bottom: 18px; line-height: 1.5; }
.footer-bottom { display: flex; justify-content: space-between; gap: 16px; padding-top: 22px; padding-bottom: 22px; border-top: 1px solid #333; font-family: var(--f-mono); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; color: #8c857b; }
.stars { color: var(--gold); display: inline-flex; gap: 3px; }

/* details / faq */
.faq { border-top: 1px solid var(--line); }
.faq details { border-bottom: 1px solid var(--line); }
.faq summary { list-style: none; cursor: pointer; display: flex; justify-content: space-between; align-items: center; gap: 20px; padding: 20px 0; font-family: var(--f-display); font-size: 21px; letter-spacing: -.01em; }
.faq summary::-webkit-details-marker { display: none; }
.faq summary svg { transition: transform .2s; flex-shrink: 0; } .faq details[open] summary svg { transform: rotate(180deg); }
.faq details p { color: var(--muted); padding: 0 40px 22px 0; max-width: 62ch; }

/* items list (service) */
.items { display: grid; grid-template-columns: 1fr 1fr; gap: 0 28px; margin-top: 44px; }
.items li { border-top: 1px solid var(--line); padding: 18px 0 22px; }
.items .mono { color: var(--gold); font-size: 10px; display: block; margin-bottom: 10px; }
.items h3 { font-size: 20px; margin-bottom: 6px; } .items p { color: var(--muted); font-size: 14px; }
.side { background: var(--white); border: 1px solid var(--line); }
.side-body { padding: 24px; display: grid; gap: 12px; }
.side-body h3 { font-size: 20px; } .side-body .small { color: var(--dim); }
.rate { display: flex; gap: 10px; align-items: center; font-family: var(--f-mono); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; }
.quote-band { background: #f3ebe0; padding: 80px 0; text-align: center; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.quote { font-size: clamp(26px, 3.4vw, 38px); font-style: italic; line-height: 1.25; max-width: 28em; margin: 14px auto 0; }
.quote-band .eyebrow { color: var(--gold); }

/* reviews */
.rev-wrap { display: grid; grid-template-columns: 1fr 2fr; gap: 56px; }
.rev-list { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; align-items: start; }
.rev { background: var(--white); border: 1px solid var(--line); padding: 24px; }
.rev p.t { color: var(--muted); font-size: 15px; margin: 16px 0 20px; }
.rev-by { border-top: 1px solid var(--line); padding-top: 14px; font-family: var(--f-mono); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
.rev-by span { color: var(--dim); display: block; margin-top: 2px; }
.reply { border-left: 2px solid var(--gold); padding-left: 14px; margin-top: 18px; }
.reply .mono { color: var(--gold); font-size: 9px; } .reply p { font-family: var(--f-display); font-style: italic; font-size: 17px; line-height: 1.3; margin-top: 6px; }

/* about */
.about-card { border: 1px solid var(--line); background: var(--white); padding: 24px; margin-top: 28px; display: grid; gap: 14px; }
.pillars { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; }
.pillars p { color: var(--muted); font-size: 14px; margin-top: 10px; }
blockquote.q { margin: 40px 0 0; border-left: 2px solid var(--gold); padding-left: 20px; }
blockquote.q p { font-family: var(--f-display); font-style: italic; font-size: 22px; letter-spacing: -.02em; }
blockquote.q cite { display: block; margin-top: 10px; font-style: normal; font-family: var(--f-mono); font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--dim); }

/* pros */
.checks li { display: flex; gap: 12px; align-items: baseline; font-size: 14px; margin-bottom: 14px; color: var(--muted); }
.checks svg { flex-shrink: 0; transform: translateY(2px); color: var(--ink); }
.trio { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 14px; }
.trio > div { border-top: 1px solid var(--line); padding-top: 14px; }
.trio h3 { font-size: 17px; margin-bottom: 6px; } .trio p { font-size: 12px; color: var(--muted); line-height: 1.55; }
.steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-top: 44px; }
.steps li { border-top: 1px solid var(--line); padding-top: 18px; }
.steps .mono { color: var(--gold); font-size: 10px; } .steps h3 { margin: 12px 0 8px; font-size: 22px; } .steps p { color: var(--muted); font-size: 14px; }
.box { background: var(--white); border: 1px solid var(--line); padding: 32px 36px; display: flex; justify-content: space-between; align-items: center; gap: 32px; }
.box p { color: var(--muted); margin-top: 8px; font-size: 15px; }

/* contact */
.contact-grid { display: grid; grid-template-columns: 1.45fr 1fr; gap: 56px; align-items: start; }
.form-card { background: var(--white); border: 1px solid var(--line); padding: 40px; }
.form-soon { display: grid; gap: 18px; justify-items: start; }
.form-soon p:not(.eyebrow) { color: var(--muted); max-width: 52ch; }
.direct { background: var(--dark); color: #fff; padding: 26px 28px; }
.direct .mono { color: var(--gold); }
.direct a { display: flex; align-items: center; gap: 12px; font-family: var(--f-display); font-size: 36px; letter-spacing: -.02em; margin: 8px 0 6px; }
.direct p:last-child { font-size: 13px; color: #c9c3b8; }
.infos { background: var(--white); border: 1px solid var(--line); margin-top: 16px; }
.infos > div { padding: 22px 26px; display: grid; grid-template-columns: 24px 1fr; gap: 14px; border-top: 1px solid var(--line); }
.infos > div:first-child { border-top: 0; }
.infos .mono { font-size: 9px; color: var(--dim); display: block; margin-bottom: 6px; }
.infos dl { margin: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 2px 16px; font-size: 15px; } .infos dd { margin: 0; color: var(--muted); }
.map { margin-top: 16px; border: 1px solid var(--line); aspect-ratio: 16 / 7; } .map iframe { width: 100%; height: 100%; border: 0; }
.legal h2 { font-size: 26px; margin: 36px 0 10px; }

/* responsive */
@media (max-width: 960px) {
  .split, .split--rev, .rev-wrap, .contact-grid { grid-template-columns: 1fr; gap: 40px; }
  .grid3 { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .cta-in, .box, .urgent { flex-direction: column; align-items: flex-start; }
  .nav { position: fixed; inset: 80px 0 auto 0; background: var(--bg); border-bottom: 1px solid var(--line); flex-direction: column; gap: 0; padding: 8px 24px 20px; display: none; }
  .nav.is-open { display: flex; } .nav a { padding: 14px 0; border-bottom: 1px solid var(--line); }
  .nav-phone-m { display: block; color: var(--ink) !important; }
  .header-phone { display: none; } .burger { display: block; }
}
@media (max-width: 640px) {
  .section { padding: 56px 0; } .hero-page { padding-bottom: 44px; }
  .grid3, .work-grid, .items, .pillars, .trio, .steps, .rev-list { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; } .footer-bottom { flex-direction: column; }
  .cta-btns { flex-direction: column; width: 100%; } .cta-btns .btn { width: 100%; }
  .form-card { padding: 24px; } .logo-sub { display: none; }
}
@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }

/* ---------- accueil / identique maquette ---------- */
h1 em, h2 em { font-style: italic; color: var(--green); }
.label { display: flex; align-items: center; gap: 14px; font-family: var(--f-mono); font-size: 10px; letter-spacing: .18em; text-transform: uppercase; margin-bottom: 22px; }
.label b { font-weight: 400; color: var(--gold); } .label i { width: 30px; height: 1px; background: var(--line); display: block; }
.sec-lead { color: var(--muted); max-width: 62ch; margin-top: 22px; margin-bottom: 52px; }

.hero-home { padding: 88px 0 96px; }
.hero-home .container { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: start; }
.hero-home h1 { font-size: clamp(46px, 5.6vw, 76px); max-width: 9.5em; line-height: 1; }
.hero-home .lead { max-width: 46ch; margin-top: 26px; }
.hero-btns { display: flex; gap: 10px; margin-top: 32px; flex-wrap: wrap; }
.hero-rate { display: flex; align-items: center; gap: 12px; margin-top: 30px; font-family: var(--f-mono); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; flex-wrap: wrap; }
.hero-rate .sep { width: 1px; height: 12px; background: var(--line); } .hero-rate .dim { color: var(--muted); }
.hero-photo { position: relative; padding-bottom: 28px; }
.hero-photo::before { content: ""; position: absolute; left: -10px; top: 12px; right: 12px; bottom: 0; border: 1px solid #e3cfa8; pointer-events: none; }
.hero-photo .caption { position: relative; padding-left: 4px; }

.urgence { background: var(--green); color: #fff; padding: 36px 0; }
.urgence .container { display: flex; justify-content: space-between; align-items: center; gap: 40px; }
.urgence-l { display: flex; gap: 18px; align-items: flex-start; } .urgence-l svg { color: var(--gold); margin-top: 6px; flex-shrink: 0; }
.urgence .mono { color: var(--gold); font-size: 9px; display: block; margin-bottom: 4px; }
.urgence h2 { font-size: 30px; margin-bottom: 8px; }
.urgence p.t { color: #c9d4cc; font-size: 14px; max-width: 54ch; }
.urgence-r { text-align: left; flex-shrink: 0; }
.urgence-r .btn { background: transparent; color: #fff; border-color: rgba(255,255,255,.35); }
.urgence-r .btn:hover { border-color: #fff; }
.urgence-r .mono { color: #9fb0a5; margin: 12px 0 0; font-size: 9px; }

.trust { background: var(--bg-alt); border-bottom: 1px solid var(--line); }
.trust .container { display: grid; grid-template-columns: repeat(3, 1fr); }
.trust-i { padding: 20px 24px; border-left: 1px solid var(--line); display: flex; align-items: center; gap: 12px; justify-content: center; }
.trust-i:first-child { border-left: 0; }
.trust-i div { border-left: 1px solid var(--gold); padding-left: 12px; }
.trust-i:first-child div { border: 0; padding: 0; }
.trust-i strong { font-family: var(--f-display); font-weight: 400; font-size: 18px; display: block; line-height: 1.2; }
.trust-i span.mono { font-size: 8px; color: var(--dim); letter-spacing: .16em; }

.tabs-card { background: var(--white); border: 1px solid var(--line); padding: 8px 8px 0; }
.tabs-card h3 { font-size: 17px; margin-top: 14px; padding: 0 6px; } .tabs-card .mono { font-size: 8px; color: var(--dim); display: block; padding: 4px 6px 14px; }

.why { display: grid; grid-template-columns: 5fr 7fr; gap: 72px; align-items: end; }
.why .photo { aspect-ratio: 4/5 !important; }
.why ol { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); align-self: start; }
.why li { display: grid; grid-template-columns: 38px 1fr; padding: 18px 0 20px; border-bottom: 1px solid var(--line); }
.why li .mono { color: var(--gold); font-size: 9px; padding-top: 4px; } .why li h3 { font-size: 20px; } .why li p { color: var(--muted); font-size: 14px; margin-top: 4px; }

.rev-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; align-items: stretch; }
.rev-grid .rev { display: flex; flex-direction: column; position: relative; }
.rev-grid .rev .t { flex: 1; }
.rev-q { position: absolute; top: 16px; right: 20px; font-family: var(--f-display); font-size: 40px; line-height: 1; color: #e3cfa8; }
.rev-foot { display: flex; justify-content: space-between; align-items: center; gap: 16px; border-top: 1px solid var(--line); margin-top: 28px; padding-top: 18px; flex-wrap: wrap; }

.pros { background: var(--dark); color: #fff; padding: 88px 0; }
.pros .container { display: grid; grid-template-columns: 1fr 1fr; gap: 72px; align-items: end; }
.pros .photo { aspect-ratio: 3/2 !important; }
.pros .eyebrow { color: var(--gold); } .pros h2 { margin-bottom: 20px; max-width: 14em; }
.pros .p { color: #c9c3b8; font-size: 15px; margin-bottom: 28px; max-width: 56ch; }
.pros dl { margin: 0; border-top: 1px solid #333; } .pros dl > div { padding: 16px 0 18px; border-bottom: 1px solid #333; }
.pros dt { font-family: var(--f-display); font-size: 18px; } .pros dd { margin: 4px 0 0; color: #a39d92; font-size: 13px; }
.pros .link-u { margin-top: 28px; color: #fff; }

.zone { display: grid; grid-template-columns: 1fr 1.3fr; gap: 72px; align-items: start; }
.zone h3 { display: flex; align-items: center; gap: 10px; font-size: 22px; margin-bottom: 10px; }
.zone p { color: var(--muted); font-size: 14px; max-width: 46ch; } .zone .mono { font-size: 9px; color: var(--dim); display: block; margin-top: 14px; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; }
.chip { font-family: var(--f-mono); font-size: 9px; letter-spacing: .14em; text-transform: uppercase; padding: 9px 13px; background: var(--white); border: 1px solid var(--line); }
.chip--d { border-style: dashed; background: transparent; color: var(--dim); }

.field { display: grid; gap: 8px; } .field > span, .fl { font-family: var(--f-mono); font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); }
.field input, .field select, .field textarea { width: 100%; font: inherit; font-size: 15px; color: var(--ink); background: #f6f2ea; border: 1px solid #ddd5c6; padding: 14px 16px; border-radius: 0; }
.field textarea { min-height: 130px; resize: vertical; } .field ::placeholder { color: #a39d92; }
.field input:focus, .field select:focus, .field textarea:focus { outline: 2px solid var(--gold); outline-offset: -1px; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.form-grid .full { grid-column: 1 / -1; }
.urgent-check { display: flex; align-items: center; gap: 12px; background: #f6f2ea; border: 1px solid #ddd5c6; padding: 14px 16px; font-size: 15px; cursor: pointer; }
.photos-btn { display: inline-flex; align-items: center; gap: 10px; border: 1px dashed #c9bfae; padding: 12px 16px; font-family: var(--f-mono); font-size: 10px; letter-spacing: .16em; text-transform: uppercase; background: transparent; cursor: pointer; justify-self: start; color: var(--ink); border-radius: 6px; }
.form-note { font-size: 12px; color: var(--dim); }
.form-act { display: flex; align-items: center; gap: 22px; flex-wrap: wrap; }
.form-act .call { display: inline-flex; gap: 8px; align-items: center; font-family: var(--f-mono); font-size: 10px; letter-spacing: .16em; text-transform: uppercase; border-bottom: 1px solid var(--gold); padding-bottom: 3px; color: var(--muted); }
.form-note a { border-bottom: 1px solid var(--gold); }
.form-msg { font-size: 14px; color: var(--green); }
.contact-grid .form-card { display: grid; gap: 20px; align-content: start; }

@media (max-width: 960px) {
  .hero-home .container, .why, .pros .container, .zone { grid-template-columns: 1fr; gap: 40px; }
  .rev-grid { grid-template-columns: repeat(2, 1fr); }
  .urgence .container { flex-direction: column; align-items: flex-start; }
  .trust .container { grid-template-columns: 1fr; } .trust-i { border-left: 0; border-top: 1px solid var(--line); justify-content: flex-start; } .trust-i:first-child { border-top: 0; }
  .hero-photo { margin-left: 10px; }
}
@media (max-width: 640px) {
  .rev-grid, .form-grid { grid-template-columns: 1fr; } .hero-home { padding: 48px 0 56px; } .pros { padding: 56px 0; }
}

/* Exterior-joinery detail pages only; preserve all shared page styles above. */
.renovation-service-page .hero-page h1 { max-width: none; }
.renovation-service-page { min-width: 0; overflow-wrap: anywhere; }
.renovation-service-page .split > *, .renovation-service-page .rev-wrap > *, .renovation-service-page .rev-list > *, .renovation-service-page .box > * { min-width: 0; }
.renovation-service-page .rate { flex-wrap: wrap; }
.renovation-service-page .rev-foot { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; margin-top: 28px; padding-top: 20px; border-top: 1px solid var(--line); }
.renovation-service-page .rev-foot + .note { margin-top: 16px; }
